{
    var ps = string.Join(", ", Array.ConvertAll(c.GetParameters(), p => $"[{string.Join(",", p.GetCustomAttributes(true).Select(a => a.GetType().Name))}] {p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"TheoryAttribute ctor({ps})");
}
EOF
